export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const safeURL=u=>{try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}};
export const stamp=s=>s?String(s).replace('T',' ').replace('Z',' UTC'):'未提供';
export const links=urls=>urls.filter(safeURL).map((u,n)=>`<a href="${esc(safeURL(u))}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).hostname)}${n?' · '+(n+1):''} ↗</a>`).join('');
export function itemHTML(i,n=0,hero=false){return `<article class="${hero?'hero':'news-row'}" data-item="${esc(i.event_id)}">${hero?'':`<span class="number">${String(n+1).padStart(2,'0')}</span>`}<div>${hero?'<div class="eyebrow">本期重点</div>':''}<${hero?'h2':'h3'}>${esc(i.title)}</${hero?'h2':'h3'}><p>${esc(i.summary)}</p>${i.frontend_takeaway?`<p class="detail">应用参考：${esc(i.frontend_takeaway)}</p>`:''}${i.limitation?`<p class="notice detail">边界：${esc(i.limitation)}</p>`:''}<div class="row-meta"><span class="tag">${esc(i.groupLabel)}</span><span>${esc(i.digest_id)} · 事件时间 ${esc(stamp(i.event_at))}</span></div><div class="evidence">${links(i.urls)}<br>核验时间 ${esc(stamp(i.checked_at))}</div>${hero&&i.focus_reason?`<p class="notice detail">入选理由：${esc(i.focus_reason)}</p>`:''}</div></article>`}
export function offerHTML(o){return `<article class="column-card"><h3>${esc(o.provider)}</h3><p>${esc(o.kindLabel)}</p>${/unverified|partial|auto_only|availability_not_tested/.test(o.status)?'<p class="notice">核验边界：免费计划或政策有官方依据，但具体型号、额度或当前可用性仍有未确认项；请勿按确定可领权益预算。</p>':''}${o.models.length?`<ul class="model-list">${o.models.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:'<p>未核实可单独选择的免费模型，不承诺全模型免费。</p>'}${(o.other_models||[]).map(g=>`<p>${esc(g.names.join('、'))}：${esc(g.quota)}</p>`).join('')}<p>额度：${esc(o.quota)}</p>${['conditions','expiry','privacy','caution'].filter(k=>o[k]).map(k=>`<p>${({conditions:'条件',expiry:'有效期',privacy:'隐私',caution:'注意'})[k]}：${esc(o[k])}</p>`).join('')}<div class="evidence">${links(o.sources)}<br>核验时间 ${esc(stamp(o.checked_at))} · 官方页面核验，未注册或调用实测</div></article>`}
export function matches(i,q,group='all'){return(group==='all'||i.group===group)&&(!q||JSON.stringify(i).toLowerCase().includes(q.toLowerCase().trim()))}
